        <textarea class="inp" style="margin-top:8px" rows="2" v-model="editing.visualIdentity.distinctiveFeatures" placeholder="\u8BC6\u522B\u7279\u5F81\uFF1A\u75E3\u3001\u7709\u773C\u3001\u8F6E\u5ED3\u3001\u914D\u9970\u7B49"/>
