        <input class="inp" style="margin-top:8px" v-model="editing.visualIdentity.stableSeed" placeholder="\u7A33\u5B9A Seed\uFF08\u670D\u52A1\u652F\u6301\u65F6\u751F\u6548\uFF09"/>
