        <template v-if="editing.worldbookDraft.enabled"><input class="inp" style="margin-top:8px" v-model="editing.worldbookDraft.title" placeholder="\u4E16\u754C\u4E66\u6807\u9898"/><textarea class="inp" style="margin-top:8px" v-model="editing.worldbookDraft.content" rows="7" placeholder="\u65F6\u4EE3\u3001\u5730\u70B9\u3001\u7EC4\u7EC7\u3001\u4E8B\u4EF6\u3001\u89C4\u5219\u548C\u4E13\u6709\u540D\u8BCD"></textarea><select class="inp" style="margin-top:8px" v-model="editing.worldbookDraft.insertPosition"><option value="system-top">\u7CFB\u7EDF\u8BBE\u5B9A\u4E4B\u524D</option><option value="before-char">\u89D2\u8272\u4EBA\u8BBE\u4E4B\u524D</option><option value="after-char">\u89D2\u8272\u4EBA\u8BBE\u4E4B\u540E</option></select></template>
