  <label class="meal-label">\u5403\u4E86\u4EC0\u4E48<input v-model="form.name" class="meal-input" maxlength="100" placeholder="\u4F8B\u5982\uFF1A\u756A\u8304\u9E21\u86CB\u9762\u3001\u4E00\u676F\u62FF\u94C1"/></label>
